class ClientError(Exception): pass
class AuthError(ClientError): pass
class NotFound(ClientError): pass
class ServerError(ClientError): pass

def handle(status, body):
    if 200 <= status < 300:
        return ("ok", body)
    if 300 <= status < 400:
        return ("redirect", body.get("location"))
    if status in (401, 403):
        raise AuthError(f"status {status}")
    if status == 404:
        raise NotFound("no such resource")
    if 400 <= status < 500:
        raise ClientError(f"status {status}: {body.get('error')}")
    raise ServerError(f"status {status}")

