class NotFound(Exception): pass
class RateLimited(Exception):
    def __init__(self, retry_after):
        super().__init__(f"rate limited; retry after {retry_after}s")
        self.retry_after = retry_after
class ApiDown(Exception): pass

RESPONSES = {
    "/users/9": (404, {}, {}),
    "/search": (429, {"Retry-After": "12"}, {}),
    "/orders": (503, {}, {}),
    "/users/7": (200, {}, {"id": 7, "name": "Ada"}),
}

def get(path):
    status, headers, body = RESPONSES[path]
    if status == 200:
        return body
    if status == 404:
        raise NotFound(path)
    if status == 429:
        raise RateLimited(int(headers.get("Retry-After", "60")))
    if status >= 500:
        raise ApiDown(f"{path} returned {status}")
    raise RuntimeError(f"unexpected {status} for {path}")

for path in RESPONSES:
    try:
        print(path, "->", get(path))
    except (NotFound, RateLimited, ApiDown) as e:
        print(path, "-> raises", type(e).__name__, "-", e)

