os.environ["SHOP_API_KEY"] = "sk-demo-secret"
LOG = []
ITEMS = [{"id": i, "sku": f"SKU-{i}"} for i in range(1, 8)]
state = {"flaky_calls": 0}

def transport(method, path, headers, params):
    LOG.append(f"{method} {path} corr={headers.get('X-Correlation-Id')} auth=***")
    if headers.get("Authorization") != "Bearer sk-demo-secret":
        return 401, {}, json.dumps({"error": "unauthorized"})
    if path == "/v1/items":
        state["flaky_calls"] += 1
        if state["flaky_calls"] == 1:
            return 503, {}, json.dumps({"error": "try again"})
        start = int(params.get("cursor", "0"))
        page = ITEMS[start:start + 3]
        nxt = start + 3
        body = {"items": page, "next_cursor": str(nxt) if nxt < len(ITEMS) else None}
        return 200, {}, json.dumps(body)
    return 404, {}, json.dumps({"error": "not found"})

