    def __init__(self):
        self.key = os.environ["SHOP_API_KEY"]
        self.corr = "checkout-sync-1"
    def _headers(self):
        return {"Authorization": f"Bearer {self.key}", "X-Correlation-Id": self.corr}
    def _get(self, path, params=None):
        for attempt in range(3):
            status, _, raw = transport("GET", path, self._headers(), params or {})
            if status == 200:
                return json.loads(raw)
            if status in (429, 500, 502, 503, 504) and attempt < 2:
                continue
            if status == 401:
                raise PermissionError("unauthorized: check SHOP_API_KEY")
            raise RuntimeError(f"GET {path} failed with {status}")
    def list_all_items(self):
        items, cursor = [], None
        while True:
            params = {} if cursor is None else {"cursor": cursor}
            body = self._get("/v1/items", params)
            items.extend(body["items"])
            cursor = body["next_cursor"]
            if cursor is None:
                return items

